def test_delivery_callbacks_require_poll_and_confirm_real_records(kafka_probe: KafkaProbe) -> None:
    """produce 仅入队；实际成功由 poll/flush 回调和分区完整读取共同确认。"""
    producer = kafka_probe.producer()
    identities = tuple(f"event-{index}" for index in range(12))
    tracker = AckPrefix(identities)
    callbacks = []

    def on_delivery(error, message) -> None:
        """仅成功回调推进前沿，保留 broker offset 供验证。"""
        event_id = message.key().decode()
        callbacks.append((event_id, error, message.offset()))
        tracker.record(event_id, success=error is None)

    for event_id in identities:
        producer.produce(kafka_probe.topic, key=event_id.encode(), value=b"synthetic", partition=0, on_delivery=on_delivery)
    assert callbacks == []
    assert tracker.confirmed_ids == ()
    assert producer.flush(15) == 0
    assert len(callbacks) == len(identities)
    assert all(error is None for _, error, _ in callbacks)
    assert tracker.confirmed_ids == identities
    records = kafka_probe.records()
    assert [key.decode() for key, _, _ in records] == list(identities)
    assert [offset for _, _, offset in callbacks] == list(range(len(identities)))


@pytest.mark.parametrize(("idempotent", "expected_count"), [(True, 1), (False, 2)])
def test_lost_ack_retries_inside_producer(kafka_probe: KafkaProbe, idempotent: bool, expected_count: int) -> None:
    """同一 produce 调用收到 broker 写入后丢 ACK：幂等组去重，关闭组出现重复。"""
    producer = kafka_probe.producer(idempotent=idempotent)
    broker_responded = PausePoint("broker-stored-before-ack-drop", timeout=15)
    callbacks = []
    kafka_probe.proxy.arm_drop(broker_responded)
    producer.produce(
        kafka_probe.topic, key=b"same-event", value=b"synthetic", partition=0,
        on_delivery=lambda error, message: callbacks.append((error, message.offset())),
    )
    try:
        broker_responded.wait_until_reached()
        # 与 producer 独立的消费者证明 broker 已写入，此时响应仍停在代理。
        assert kafka_probe.records() == [(b"same-event", b"synthetic", 0)]
        producer.poll(0)
        assert callbacks == []
    finally:
        broker_responded.resume()
    assert producer.flush(15) == 0
    assert len(callbacks) == 1 and callbacks[0][0] is None
    assert kafka_probe.proxy.dropped_responses == 1
    assert kafka_probe.proxy.produce_requests >= 2
    records = kafka_probe.records()
    assert len(records) == expected_count
    assert [offset for _, _, offset in records] == list(range(expected_count))


def test_empty_flush_queue_does_not_mean_delivered(kafka_probe: KafkaProbe) -> None:
    """持续丢 ACK 时队列最终清空且回调失败；broker 仍可能已经保存消息。"""
    producer = kafka_probe.producer(timeout_ms=2000)
    tracker = AckPrefix(("ambiguous-event",))
    errors = []

    def on_delivery(error, message) -> None:
        """失败不前进，不能凭 flush 的剩余数量将未确认事件标记已发布。"""
        errors.append(error)
        tracker.record("ambiguous-event", success=error is None)

    kafka_probe.proxy.arm_drop(every_response=True)
    producer.produce(kafka_probe.topic, key=b"ambiguous-event", value=b"synthetic", partition=0, on_delivery=on_delivery)
    assert producer.flush(10) == 0
    assert len(errors) == 1 and errors[0] is not None
    assert errors[0].code() == KafkaError._MSG_TIMED_OUT
    assert tracker.confirmed_ids == () and tracker.has_failure
    assert kafka_probe.proxy.dropped_responses >= 1
    assert kafka_probe.records() == [(b"ambiguous-event", b"synthetic", 0)]


def test_application_replay_with_new_producer_can_duplicate(kafka_probe: KafkaProbe) -> None:
    """应用重发不是客户端内部重试，幂等设置不会按事件身份跨实例去重。"""
    for _ in range(2):
        producer = kafka_probe.producer()
        deliveries = []
        producer.produce(
            kafka_probe.topic, key=b"replayed-event", value=b"synthetic", partition=0,
            on_delivery=lambda error, message: deliveries.append(error),
        )
        assert producer.flush(10) == 0
        assert deliveries == [None]
    records = kafka_probe.records()
    assert records == [(b"replayed-event", b"synthetic", 0), (b"replayed-event", b"synthetic", 1)]
